package com.retailflow.pos.staff;
import jakarta.persistence.EntityNotFoundException;import java.time.LocalDate;import java.util.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;
@Service public class StaffService{private final StaffRepository r;private final AttendanceRepository a;private final PasswordEncoder e;public StaffService(StaffRepository r,AttendanceRepository a,PasswordEncoder e){this.r=r;this.a=a;this.e=e;}public List<Staff>list(){return r.findAll();}public Staff get(String id){return r.findById(id).orElseThrow(()->new EntityNotFoundException("Staff not found"));}public Staff save(Staff s){if(s.getPasswordHash()!=null&&!s.getPasswordHash().startsWith("$2"))s.setPasswordHash(e.encode(s.getPasswordHash()));return r.save(s);}public void delete(String id){r.delete(get(id));}public List<AttendanceRecord>attendance(LocalDate d){return d==null?a.findAll():a.findByRecordDate(d);}public AttendanceRecord saveAttendance(AttendanceRecord v){return a.save(v);}}
